    const SmartObjectBlueprint *FindSmartObjectBlueprint(std::string_view name) {
        for (const SmartObjectBlueprint &blueprint : g_SmartObjectBlueprints) {
            if (blueprint.name.size() != name.size()) {
                continue;
            }
            bool same = true;
            for (std::size_t index = 0; index < name.size() && same; ++index) {
                same = std::tolower(static_cast<unsigned char>(blueprint.name[index])) == std::tolower(static_cast<unsigned char>(name[index]));
            }
            if (same) {
                return &blueprint;
            }
        }
        return nullptr;
    }

    const char *SmartObjectKindName(SmartObjectKind kind) {
        switch (kind) {
        case SmartObjectKind::Seat: return "seat";
        case SmartObjectKind::Bed: return "bed";
        case SmartObjectKind::Dice: return "dice";
        case SmartObjectKind::Alchemy: return "alchemy";
        case SmartObjectKind::Smithing: return "smithing";
        case SmartObjectKind::Drying: return "drying";
        case SmartObjectKind::Smoking: return "smoking";
        case SmartObjectKind::Sharpening: return "sharpening";
        }
        return "seat";
    }
